// === Tab: mySketch ===
// The particle of index 0 is related to the position of the mouse.

var particlesQuantity = 8000; // 18000

var positionX = new Array(particlesQuantity);
var positionY = new Array(particlesQuantity);
var velocityX = new Array(particlesQuantity).fill(0);
var velocityY = new Array(particlesQuantity).fill(0);

const drag = 0.96;

// const falloff_intensity = 400;
//let falloff_curve = x => 0.2*pow(exp(-(x / falloff_intensity) ^ 2) , 0.25); // bell curve
//const area_of_influence = 30;
//let falloff_curve = x => 0.6 * area_of_influence * Math.tanh(1 / (x / area_of_influence));
const area_of_influence = 60;
let falloff_curve = x => area_of_influence * ( Math.tanh(Math.log(1 / (x / area_of_influence))) + 1);

function setup() {
	createCanvas(windowWidth, windowHeight);
	stroke(64, 255, 255);
	//strokeWeight(5);

	for (var particle = 1; particle < particlesQuantity; particle++) {
		positionX[particle] = random(0, width);
		positionY[particle] = random(0, height);
	}

	positionX[0] = 0;
	positionY[0] = 0;
}

function draw() {
	//blendMode(BLEND)
	background(0, 50)
	//blendMode(ADD)

	velocityX[0] = velocityX[0] * 0.5 + ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - positionX[0]) * 0.3;
	velocityY[0] = velocityY[0] * 0.5 + ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - positionY[0]) * 0.3;

	positionX[0] += velocityX[0];
	positionY[0] += velocityY[0];

	for (var particle = 1; particle < particlesQuantity; particle++) {
		const falloff = falloff_curve(sq(positionX[0] - positionX[particle]) + sq(positionY[0] - positionY[particle]));

		velocityX[particle] = velocityX[particle] * drag + (velocityX[0] - velocityX[particle]) * falloff //* random()
		velocityY[particle] = velocityY[particle] * drag + (velocityY[0] - velocityY[particle]) * falloff //* random()

		positionX[particle] += 1.5 * velocityX[particle];
		positionY[particle] += 1.5 * velocityY[particle];

		// loop position
		if (positionX[particle] < 0 && velocityX[particle] < 0) {
			//velocityX[particle] = -velocityX[particle];
			positionX[particle] = width;
		}

		if (positionY[particle] < 0 && velocityY[particle] < 0) {
			//velocityY[particle] = -velocityY[particle];
			positionY[particle] = height;
		}

		if (positionX[particle] > width && velocityX[particle] > 0) {
			//velocityX[particle] = -velocityX[particle];
			positionX[particle] = 0;
		}

		if (positionY[particle] > height && velocityY[particle] > 0) {
			//velocityY[particle] = -velocityY[particle];
			positionY[particle] = 0;
		}

		// draw the particles
		point(positionX[particle], positionY[particle]);
	}

	/*
	// random displacements
	for (let i = 0; i < 0.1 * particlesQuantity; i++) {
		const k = floor(random(1, particlesQuantity));
		positionX[k] = random(0, width);
		positionY[k] = random(0, height);
	}
	*/
}

function mousePressed() {
	for (var particle = 1; particle < particlesQuantity; particle++) {
		positionX[particle] = random(0, width);
		positionY[particle] = random(0, height);
		velocityX[particle] = 0;
		velocityY[particle] = 0;
	}
	stroke(random(100, 255), random(100, 255), random(100, 255));
}

